from odds import american_probability


def _parse_aware_iso(s):
    if not isinstance(s, str):
        raise ValueError("timestamp must be a string")
    s = s.strip()
    if not s:
        raise ValueError("empty timestamp string")
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        raise ValueError("timestamp must be timezone-aware")
    return dt


def select_latest(rows, asof):
    if not isinstance(asof, datetime):
        raise ValueError("asof must be a datetime")
    if asof.tzinfo is None:
        raise ValueError("asof must be timezone-aware")

    best = None
    best_obs = None
    best_id = None

    for row in rows:
        if not isinstance(row, dict):
            continue

        row_id = row.get("id")
        if not isinstance(row_id, str) or not row_id:
            continue

        odds_val = row.get("odds")
        try:
            american_probability(odds_val)
        except (ValueError, TypeError):
            continue

        try:
            observed_at = _parse_aware_iso(row.get("observed_at"))
        except (ValueError, TypeError):
            continue

        try:
            expires_at = _parse_aware_iso(row.get("expires_at"))
        except (ValueError, TypeError):
            continue

        if not (observed_at < expires_at):
            continue
        if not (observed_at <= asof < expires_at):
            continue

        if best is None:
            best = row
            best_obs = observed_at
            best_id = row_id
        else:
            if observed_at > best_obs:
